// routes/watchlist.js
const express = require('express');
const mongoose = require('mongoose');
const User = require('../models/User');
const Movie = require('../models/Movie');
const auth = require('../middleware/auth'); // sets req.user from JWT

const router = express.Router();
router.use(auth);

const WINDOW_MS = 2 * 60_000, LIMIT = 10;
const ops = new Map(); // userId -> [timestamps]
function addLimiter(req, res, next) {
  const now = Date.now();
  const list = (ops.get(req.user.id) || []).filter((t) => now - t < WINDOW_MS);
  if (list.length >= LIMIT) return res.status(429).json({ message: 'Too many watchlist operations' });
  list.push(now);
  ops.set(req.user.id, list);
  next();
}
const validId = (id) => mongoose.Types.ObjectId.isValid(id);

router.get('/', async (req, res, next) => {
  try {
    const user = await User.findById(req.user.id).populate('watchlist');
    res.json(user ? user.watchlist : []);
  } catch (e) { next(e); }
});

router.get('/check/:movieId', async (req, res, next) => {
  try {
    if (!validId(req.params.movieId)) return res.status(400).json({ message: 'Invalid movie id' });
    const found = await User.exists({ _id: req.user.id, watchlist: req.params.movieId });
    res.json({ inWatchlist: Boolean(found) });
  } catch (e) { next(e); }
});

router.post('/add', addLimiter, async (req, res, next) => {
  try {
    const { movieId } = req.body;
    if (!validId(movieId)) return res.status(400).json({ message: 'Invalid movie id' });
    if (!(await Movie.exists({ _id: movieId }))) return res.status(404).json({ message: 'Movie not found' });
    const r = await User.updateOne({ _id: req.user.id }, { $addToSet: { watchlist: movieId } });
    res.status(r.modifiedCount ? 201 : 200)
      .json({ message: r.modifiedCount ? 'Added to watchlist' : 'Already in watchlist' });
  } catch (e) { next(e); }
});

router.delete('/remove/:movieId', async (req, res, next) => {
  try {
    if (!validId(req.params.movieId)) return res.status(400).json({ message: 'Invalid movie id' });
    const r = await User.updateOne({ _id: req.user.id }, { $pull: { watchlist: req.params.movieId } });
    if (!r.modifiedCount) return res.status(404).json({ message: 'Movie not in watchlist' });
    res.json({ message: 'Removed from watchlist' });
  } catch (e) { next(e); }
});

module.exports = router;
